  abortSession: { id: string | number; };
  acceptExtensionSuggestions: Record<string, never>;
  advanceWorkflowRun: { id: string | number; };
  applyExtensionMetaPack: { meta_pack_id: string | number; };
  applyExtensionPackProfile: { pack_id: string | number; profile_name: string | number; };
  applyExtensionPackUpdate: { pack_id: string | number; };
